7234	func maskSQLLiteralContentsForSearch(content string) string {
7235		masked := []byte(content)
7236		for i := 0; i < len(content); {
7237			switch content[i] {
7238			case '\'', '"':
7239				quote := content[i]
7240				backslashEscapes := quote == '\'' && postgresEscapeStringPrefix(content, i)
7241				i++ // preserve the opening quote
7242				for i < len(content) {
7243					if backslashEscapes && content[i] == '\\' && i+1 < len(content) {
7244						masked[i] = ' '
7245						if content[i+1] != '\n' && content[i+1] != '\r' {
7246							masked[i+1] = ' '
7247						}
7248						i += 2
7249						continue
7250					}
7251					if content[i] == quote {
7252						if i+1 < len(content) && content[i+1] == quote {
7253							masked[i] = ' '
7254							masked[i+1] = ' '
7255							i += 2
7256							continue
7257						}
7258						i++ // preserve the closing quote
