7260					}
7261					if content[i] != '\n' && content[i] != '\r' {
7262						masked[i] = ' '
7263					}
7264					i++
7265				}
7266			case '$':
7267				tag, ok := dollarQuoteTag(content, i)
7268				if !ok {
7269					i++
7270					continue
7271				}
7272				bodyStart := i + len(tag)
7273				closeRel := strings.Index(content[bodyStart:], tag)
7274				if closeRel < 0 {
7275					i = bodyStart
7276					continue
7277				}
7278				bodyEnd := bodyStart + closeRel
7279				maskBytesPreservingNewlines(masked, bodyStart, bodyEnd)
7280				i = bodyEnd + len(tag)
