7288	func postgresEscapeStringPrefix(content string, quote int) bool {
7289		if quote < 1 || (content[quote-1] != 'E' && content[quote-1] != 'e') {
7290			return false
7291		}
7292		prefix := quote - 1
7293		if prefix == 0 {
7294			return true
7295		}
7296		previous := content[prefix-1]
7297		return !isWordByte(previous) && previous != '$'
7298	}
