package sem

import (
	"strings"
	"testing"
)

func TestPostgresIdentityAndCheckMigrations(t *testing.T) {
	// Identity syntax: https://www.postgresql.org/docs/18/sql-createtable.html
	// The named CHECK expressions reproduce River's initial migration:
	// https://github.com/riverqueue/river/blob/03b193e2a263b52ac523de36eafa45375c1b99b6/riverdriver/riverdatabasesql/migration/main/002_initial_schema.up.sql
	for name, definition := range map[string]string{
		"identity_default":        "id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY",
		"identity_always":         "id bigint GENERATED ALWAYS AS IDENTITY",
		"identity_options":        "id bigint GENERATED\nBY DEFAULT AS IDENTITY (START WITH 7 INCREMENT BY 5) PRIMARY KEY",
		"identity_comments":       "id bigint GeNeRaTeD /* generation */ BY -- mode\n DEFAULT AS IDENTITY (START WITH 7) NOT NULL",
		"identity_always_options": "id bigint GENERATED ALWAYS AS IDENTITY (START WITH 7 INCREMENT BY 5)",
		"river_checks": `state text, finalized_at timestamp, max_attempts smallint,
    CONSTRAINT finalized_or_finalized_at_null CHECK ((state IN ('cancelled', 'completed', 'discarded') AND finalized_at IS NOT NULL) OR finalized_at IS NULL),
    CONSTRAINT max_attempts_is_positive CHECK (max_attempts > 0)`,
		"inline_named_check": `id int CONSTRAINT positive CHECK (id > 0), label text`,
		"unnamed_check":      `id int, CHECK (id > 0)`,
		"short_check":        `id int, CHECK(true)`,
		"quoted_check":       `"odd)name" text, CONSTRAINT "check's ""name" CHECK ("odd)name" <> E'it\'s )')`,
		"multiline_check":    "id int, CONSTRAINT\npositive\nCHECK\n(id > 0), label text",
		"inline_checks":      `id int CHECK (id > 0) CHECK (id < 20), label text`,
		"dollar_check":       `label text, CHECK (label <> $tag$can't ) ; CHECK (false)$tag$)`,
	} {
		t.Run(name, func(t *testing.T) {
			src := "CREATE TABLE before_tbl (id int);\nCREATE TABLE subject (\n" + definition + "\n);\nCREATE TABLE after_tbl (id int);\n"
			entities, _, status := TreeSitterParser{}.ParseWithStatus("migration.sql", src)
			if status.ParseError {
				t.Fatalf("unexpected parse error: %s\nmasked:\n%s", status.Detail, maskPostgresUnsupportedSyntax(src))
			}
			for _, table := range []string{"before_tbl", "subject", "after_tbl"} {
				if countEntity(entities, "table", table) != 1 {
					t.Errorf("missing table %s: %+v", table, entities)
				}
			}
			masked := maskPostgresUnsupportedSyntax(src)
			if len(masked) != len(src) || strings.Count(masked, "\n") != strings.Count(src, "\n") {
				t.Fatal("mask changed source offsets")
			}
			for i := range src {
				if (src[i] == '\n' || src[i] == '\r') && masked[i] != src[i] {
					t.Fatalf("newline moved at byte %d", i)
				}
			}
			for _, entity := range entities {
				if entity.Name == "after_tbl" && entity.StartLine != strings.Count(src, "\n") {
					t.Errorf("following table moved: %+v", entity)
				}
			}
		})
	}
}

func TestPostgresIdentityCheckTextIsNotSyntax(t *testing.T) {
	for _, value := range []string{
		`'GENERATED BY DEFAULT AS IDENTITY (START WITH 7) CHECK (false)'`,
		`E'it\'s CHECK (false) GENERATED ALWAYS AS IDENTITY'`,
		`$tag$CHECK (false) GENERATED BY DEFAULT AS IDENTITY$tag$`,
		`"CHECK (false) GENERATED BY DEFAULT AS IDENTITY"`,
	} {
		src := "CREATE TABLE t (label text DEFAULT " + value + ");"
		if got := maskPostgresUnsupportedSyntax(src); got != src {
			t.Errorf("quoted text was changed:\n%s\n%s", src, got)
		}
	}
}

func TestPostgresIdentityCheckMalformedClausesStillFail(t *testing.T) {
	for _, src := range []string{
		"CREATE TABLE t (id bigint GENERATED BY AS IDENTITY);",
		"CREATE TABLE t (id bigint GENERATED BY DEFAULT AS IDENTITY (START WITH 7;",
		"CREATE TABLE t (id int, CONSTRAINT positive CHECK (id > 0;",
		"CREATE TABLE t (id int CHECK (id > 0; CREATE TABLE after_tbl (id int);",
	} {
		if _, _, status := (TreeSitterParser{}).ParseWithStatus("bad.sql", src); !status.ParseError {
			t.Errorf("malformed SQL reported as complete: %s", src)
		}
	}
}

func TestPostgresIdentityCheckSnapshot(t *testing.T) {
	repo := t.TempDir()
	writeFile(t, repo, "001_identity.sql", "CREATE TABLE records (id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY);\n")
	writeFile(t, repo, "002_checks.sql", `CREATE TABLE jobs (
    id bigint GENERATED ALWAYS AS IDENTITY,
    attempt int,
    priority int,
    CONSTRAINT attempt_positive CHECK (attempt > 0),
    CONSTRAINT priorité_范围 CHECK (priority BETWEEN 1 AND 4)
);
CREATE INDEX jobs_priority ON jobs (priority);
CREATE TABLE after_jobs (id int);
`)
	writeFile(t, repo, "003_bad.sql", "CREATE TABLE broken (id bigint GENERATED BY AS IDENTITY);\n")
	snapshot, err := BuildProviderSnapshot(t.Context(), repo, "test-version")
	if err != nil {
		t.Fatal(err)
	}
	if failures := snapshot.Header.PartialFailures; len(failures) != 1 || failures[0].FilePath != "003_bad.sql" || failures[0].Code != "E_PARSE_ERROR" {
		t.Fatalf("unexpected failures: %+v", failures)
	}
	for _, name := range []string{"records", "jobs", "jobs_priority", "after_jobs"} {
		found := 0
		for _, symbol := range snapshot.Symbols {
			if symbol.QualifiedName == name {
				found++
			}
		}
		if found != 1 {
			t.Errorf("expected one %s symbol; got %d: %+v", name, found, snapshot.Symbols)
		}
	}
}

